package vn.edu.library.ui;

import vn.edu.library.data.Database;
import vn.edu.library.domain.UserSession;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;

public final class ReservationsPanel extends JPanel {
    private final UserSession session;
    private final JTextField search=new JTextField(22);
    private final JLabel status=new JLabel(" ");
    private final DefaultTableModel model=new DefaultTableModel(){@Override public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    public ReservationsPanel(UserSession session){this.session=session;setLayout(new BorderLayout(0,16));setBackground(UiStyle.CANVAS);setBorder(new EmptyBorder(27,30,24,30));add(header(),BorderLayout.NORTH);table.setRowHeight(33);table.setAutoCreateRowSorter(true);table.setFillsViewportHeight(true);JScrollPane sc=new JScrollPane(table);sc.setBorder(BorderFactory.createLineBorder(new Color(229,233,240)));add(sc,BorderLayout.CENTER);status.setForeground(UiStyle.MUTED);add(status,BorderLayout.SOUTH);load();}
    private JComponent header(){JPanel h=new JPanel(new BorderLayout(0,16));h.setOpaque(false);JPanel t=new JPanel();t.setOpaque(false);t.setLayout(new BoxLayout(t,BoxLayout.Y_AXIS));JLabel title=new JLabel("Đặt trước sách");title.setFont(title.getFont().deriveFont(Font.BOLD,25f));JLabel sub=new JLabel("Duyệt yêu cầu, giữ bản sách và theo dõi hạn nhận tại thư viện.");sub.setForeground(UiStyle.MUTED);t.add(title);t.add(Box.createVerticalStrut(5));t.add(sub);h.add(t,BorderLayout.NORTH);search.putClientProperty("JTextField.placeholderText","Mã độc giả, họ tên, tên sách");JButton find=new JButton("Tìm kiếm"),refresh=new JButton("Làm mới"),approve=new JButton("Duyệt & giữ sách"),reject=new JButton("Từ chối");approve.setBackground(UiStyle.BLUE);approve.setForeground(Color.WHITE);find.addActionListener(e->load());refresh.addActionListener(e->{search.setText("");load();});search.addActionListener(e->load());approve.addActionListener(e->review(true));reject.addActionListener(e->review(false));JPanel c=new JPanel(new FlowLayout(FlowLayout.LEFT,7,0));c.setOpaque(false);for(JComponent x:new JComponent[]{search,find,refresh,approve,reject})c.add(x);h.add(c,BorderLayout.SOUTH);return h;}
    private void load(){releaseExpired();String term=search.getText().trim();String sql="SELECT r.reservation_id AS 'ID',r.member_id,m.member_code AS 'Mã độc giả',m.full_name AS 'Độc giả',b.title AS 'Tên sách',r.requested_at AS 'Ngày gửi',r.reservation_status AS 'Trạng thái',cp.barcode AS 'Bản giữ',s.full_name AS 'Người duyệt',r.expires_at AS 'Hạn nhận' FROM reservations r JOIN school_members m ON m.member_id=r.member_id JOIN books b ON b.book_id=r.book_id LEFT JOIN book_copies cp ON cp.copy_id=r.reserved_copy_id LEFT JOIN staff_profiles s ON s.staff_id=r.reviewed_by WHERE (?='' OR m.member_code LIKE ? OR m.full_name LIKE ? OR b.title LIKE ?) ORDER BY r.requested_at DESC";try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement(sql)){String p="%"+term+"%";q.setString(1,term);for(int i=2;i<=4;i++)q.setString(i,p);try(ResultSet rs=q.executeQuery()){ResultSetMetaData md=rs.getMetaData();model.setRowCount(0);model.setColumnCount(0);for(int i=1;i<=md.getColumnCount();i++)model.addColumn(md.getColumnLabel(i));while(rs.next()){Object[] a=new Object[md.getColumnCount()];for(int i=1;i<=md.getColumnCount();i++)a[i-1]=rs.getObject(i);model.addRow(a);}}status.setText("Đang hiển thị "+model.getRowCount()+" yêu cầu đặt trước.");}catch(Exception ex){model.setRowCount(0);status.setText("Không tải được yêu cầu: "+ex.getMessage());}}
    private void releaseExpired(){try(Connection c=Database.getConnection()){c.setAutoCommit(false);try(Statement s=c.createStatement()){s.executeUpdate("UPDATE book_copies cp JOIN reservations r ON r.reserved_copy_id=cp.copy_id SET cp.copy_status='AVAILABLE' WHERE cp.copy_status='RESERVED' AND r.reservation_status='READY_FOR_PICKUP' AND r.expires_at<CURRENT_TIMESTAMP");s.executeUpdate("UPDATE reservations SET reservation_status='EXPIRED' WHERE reservation_status='READY_FOR_PICKUP' AND expires_at<CURRENT_TIMESTAMP");c.commit();}catch(Exception ex){c.rollback();throw ex;}}catch(Exception ignored){}}
    private void review(boolean approve){int view=table.getSelectedRow();if(view<0){message("Chọn yêu cầu trước.",JOptionPane.INFORMATION_MESSAGE);return;}int row=table.convertRowIndexToModel(view);String state=model.getValueAt(row,6).toString();if(!"PENDING".equals(state)){message("Chỉ yêu cầu đang chờ mới được duyệt hoặc từ chối.",JOptionPane.WARNING_MESSAGE);return;}long id=Long.parseLong(model.getValueAt(row,0).toString());if(!approve){String reason=JOptionPane.showInputDialog(this,"Lý do từ chối:","Từ chối đặt trước",JOptionPane.PLAIN_MESSAGE);if(reason==null)return;updateReject(id,reason);return;}try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{long staff=staffId(c),bookId;try(PreparedStatement q=c.prepareStatement("SELECT book_id FROM reservations WHERE reservation_id=? AND reservation_status='PENDING' FOR UPDATE")){q.setLong(1,id);try(ResultSet r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException("Yêu cầu đã được xử lý.");bookId=r.getLong(1);}}long copyId;try(PreparedStatement q=c.prepareStatement("SELECT copy_id FROM book_copies WHERE book_id=? AND copy_status='AVAILABLE' ORDER BY copy_id LIMIT 1 FOR UPDATE")){q.setLong(1,bookId);try(ResultSet r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException("Hiện không còn bản sách sẵn sàng để giữ.");copyId=r.getLong(1);}}try(PreparedStatement q=c.prepareStatement("UPDATE book_copies SET copy_status='RESERVED' WHERE copy_id=? AND copy_status='AVAILABLE'")){q.setLong(1,copyId);if(q.executeUpdate()!=1)throw new IllegalArgumentException("Bản sách vừa được người khác xử lý, hãy tải lại.");}try(PreparedStatement q=c.prepareStatement("UPDATE reservations SET reservation_status='READY_FOR_PICKUP',reserved_copy_id=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,expires_at=DATE_ADD(CURRENT_TIMESTAMP,INTERVAL 3 DAY) WHERE reservation_id=?")){q.setLong(1,copyId);q.setLong(2,staff);q.setLong(3,id);q.executeUpdate();}c.commit();load();message("Đã duyệt và giữ một bản sách cho độc giả đến nhận trong 3 ngày.",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){c.rollback();throw ex;}finally{c.setAutoCommit(true);}}catch(Exception ex){message("Không duyệt được yêu cầu: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private void updateReject(long id,String reason){try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement("UPDATE reservations SET reservation_status='REJECTED',reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,note=? WHERE reservation_id=? AND reservation_status='PENDING'")){q.setLong(1,staffId(c));q.setString(2,reason);q.setLong(3,id);if(q.executeUpdate()!=1)throw new IllegalArgumentException("Yêu cầu đã được xử lý.");load();message("Đã từ chối yêu cầu.",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){message("Không từ chối được: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private long staffId(Connection c)throws SQLException{try(PreparedStatement q=c.prepareStatement("SELECT staff_id FROM accounts WHERE account_id=? AND staff_id IS NOT NULL")){q.setLong(1,session.accountId());try(ResultSet r=q.executeQuery()){if(!r.next())throw new SQLException("Tài khoản chưa liên kết nhân viên.");return r.getLong(1);}}}
    private void message(String s,int t){JOptionPane.showMessageDialog(this,s,"Đặt trước sách",t);}
}
